	/**
	 * Default Constructor
	 */
    public SupplierService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new SupplierEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(SupplierRepository.class) );
		this.validator		= applicationContext.getBean(SupplierValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Supplier
	 */
		public Supplier createSupplier( CreateSupplierCommand command ) {

		Supplier entity = new Supplier();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setSupplierId( command.getSupplierId() );
            entity.setName( command.getName() );
            entity.setSupplierType( command.getSupplierType() );
            entity.setApprovalStatus( command.getApprovalStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Supplier {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateSupplierCommand
	 * @return		Supplier
	 */
	public Supplier updateSupplier( UpdateSupplierCommand command ) {

		Supplier entity = new Supplier();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setSupplierId( command.getSupplierId() );
            entity.setName( command.getName() );
            entity.setManufacturers( command.getManufacturers() );
            entity.setComponents( command.getComponents() );
            entity.setEngineTypes( command.getEngineTypes() );
            entity.setAvionicsSuites( command.getAvionicsSuites() );
            entity.setApus( command.getApus() );
            entity.setLandingGears( command.getLandingGears() );
            entity.setSupplierType( command.getSupplierType() );
            entity.setApprovalStatus( command.getApprovalStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Supplier {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteSupplierCommand
	 */
	public void delete( DeleteSupplierCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getSupplierId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Supplier {0} ", id );

	}

	/**
	 * Method to retrieve the Supplier via SupplierFetchOneSummary
	 * @param 	summary SupplierFetchOneSummary
	 * @return 	SupplierFetchOneResponse
	 */
	public Supplier getSupplier( SupplierFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "SupplierFetchOneSummary arg cannot be null" );

		Supplier entity = null;
		UUID id = summary.getSupplierId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Supplier using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Suppliers
	 *
	 * @return 	List<Supplier>
	 */
    public List<Supplier> getAllSupplier() {
		List<Supplier> list = projector.findAll( new FindAllSupplierQuery() );
		return list;
	}


